/* eslint-disable jsx-a11y/alt-text */
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Divider,
  Fade,
  InputAdornment,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import React, { useMemo, useState } from 'react';
import NewUserDialog from './NewUserDialog';
import { useFormik } from 'formik';
import { useAppDispatch } from '../../store/hooks';
import { setEnableAuth } from './AuthSlice';
import { useLoginMutation } from '../posApi';
import { IAuth } from '../../core/Interface/api.interface';
import { appColors } from '../../theme/appColors';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import VisibilityOutlinedIcon from '@mui/icons-material/VisibilityOutlined';
import VisibilityOffOutlinedIcon from '@mui/icons-material/VisibilityOffOutlined';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import ShieldOutlinedIcon from '@mui/icons-material/ShieldOutlined';

const DEFAULT_LOGIN_ERROR_MESSAGE =
  'Login failed. Please check your username and password and try again.';

const getLoginErrorMessage = (error: unknown) => {
  if (typeof error === 'object' && error !== null) {
    if ('data' in error) {
      const data = (error as { data?: unknown }).data;

      if (typeof data === 'string' && data.trim()) {
        return data;
      }

      if (typeof data === 'object' && data !== null && 'message' in data) {
        const message = (data as { message?: unknown }).message;

        if (typeof message === 'string' && message.trim()) {
          return message;
        }
      }
    }

    if ('message' in error) {
      const message = (error as { message?: unknown }).message;

      if (typeof message === 'string' && message.trim()) {
        return message;
      }
    }
  }

  return DEFAULT_LOGIN_ERROR_MESSAGE;
};

const FIELD_SX = {
  width: '100%',
  '& .MuiOutlinedInput-root': {
    borderRadius: '10px',
    backgroundColor: '#F8FAFC',
    transition: 'all 0.2s ease',
    '& fieldset': { borderColor: '#E2E8F0', borderWidth: '1.5px' },
    '&:hover fieldset': { borderColor: '#94A3B8' },
    '&.Mui-focused': {
      backgroundColor: '#fff',
      boxShadow: '0 0 0 3px rgba(37,99,235,0.10)',
      '& fieldset': { borderColor: '#2563EB', borderWidth: '1.5px' },
    },
  },
  '& .MuiInputBase-input': {
    padding: '12px 14px 12px 0',
    fontSize: '0.9rem',
    color: '#1E293B',
    '&::placeholder': { color: '#94A3B8', opacity: 1 },
  },
};

const Login = () => {
  const dispatch = useAppDispatch();
  const [login, { isLoading }] = useLoginMutation();
  const [showPassword, setShowPassword] = useState(false);
  const [newUserOpen, setNewUserOpen] = useState(false);
  const [loginError, setLoginError] = useState('');
  const greeting = new Date().getHours() < 12 ? 'Good morning' : 'Good afternoon';

  const formik = useFormik({
    initialValues: { username: '', password: '' },
    onSubmit: async (values) => {
      setLoginError('');

      try {
        const loginResponse = await login(values).unwrap();
        if (!loginResponse.status) {
          setLoginError(loginResponse.message || DEFAULT_LOGIN_ERROR_MESSAGE);
        } else {
          const tokenData = loginResponse.data as IAuth;
          localStorage.setItem('token', tokenData.token);
          dispatch(setEnableAuth());
        }
      } catch (error) {
        setLoginError(getLoginErrorMessage(error));
      }
    },
  });

  const formValid = useMemo(
    () => formik.values.username !== '' && formik.values.password !== '',
    [formik.values]
  );

  const fillDemo = () => {
    setLoginError('');
    formik.setFieldValue('username', 'demo');
    formik.setFieldValue('password', 'demo@123');
  };

  const handleInputChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    if (loginError) {
      setLoginError('');
    }

    formik.handleChange(event);
  };

  return (
    <Fade
      in
      timeout={600}
    >
      <Box sx={{ width: '100%', maxWidth: 400, position: 'relative', zIndex: 1 }}>

        {/* Logo — desktop only (mobile sees it in the left panel header) */}
        <Box sx={{ display: { xs: 'none', md: 'flex' }, justifyContent: 'center', mb: 4 }}>
          <Box
            component="img"
            src="/images/logo.png"
            sx={{ height: 44, width: 'auto' }}
          />
        </Box>

        {/* Card */}
        <Box
          sx={{
            backgroundColor: '#fff',
            borderRadius: '16px',
            boxShadow: '0 1px 3px rgba(0,0,0,0.06), 0 8px 32px rgba(15,29,77,0.10)',
            border: '1px solid #F1F5F9',
            overflow: 'hidden',
          }}
        >
          {/* Top accent */}
          <Box sx={{ height: 3, background: 'linear-gradient(90deg, #1E3A8A 0%, #2563EB 50%, #60A5FA 100%)' }} />

          <Box sx={{ p: { xs: '28px 24px', sm: '36px 40px 40px' } }}>

            {/* Heading */}
            <Box sx={{ mb: 3.5 }}>
              <Typography
                sx={{
                  fontSize: { xs: '1.45rem', md: '1.6rem' },
                  fontWeight: 800,
                  color: '#0F172A',
                  letterSpacing: '-0.025em',
                  lineHeight: 1.2,
                  mb: 0.5,
                }}
              >
                Sign in
              </Typography>
              <Typography
                sx={{
                  fontSize: '0.875rem',
                  fontWeight: 700,
                  color: appColors.reflexBlue[80],
                  fontFamily: 'verlag, Helvetica, Arial, sans-serif',
                  lineHeight: 1.5,
                }}
              >
                {greeting}
              </Typography>
              <Typography sx={{ fontSize: '0.875rem', color: '#64748B', lineHeight: 1.5 }}>
                Enter your credentials to access your account
              </Typography>
            </Box>

            {/* Form */}
            <Box
              component="form"
              noValidate
              onSubmit={formik.handleSubmit}
            >
              <Stack spacing={2.5}>

                {/* Username */}
                <Box>
                  <Typography
                    component="label"
                    sx={{ display: 'block', fontSize: '0.8rem', fontWeight: 600, color: '#374151', mb: 0.75 }}
                  >
                    Username
                  </Typography>
                  <TextField
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <PersonOutlineIcon sx={{ color: '#94A3B8', fontSize: '1.15rem' }} />
                        </InputAdornment>
                      ),
                    }}
                    autoComplete="username"
                    fullWidth
                    name="username"
                    onBlur={formik.handleBlur}
                    onChange={handleInputChange}
                    placeholder="Enter your username"
                    sx={FIELD_SX}
                    value={formik.values.username}
                  />
                </Box>

                {/* Password */}
                <Box>
                  <Typography
                    component="label"
                    sx={{ display: 'block', fontSize: '0.8rem', fontWeight: 600, color: '#374151', mb: 0.75 }}
                  >
                    Password
                  </Typography>
                  <TextField
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <LockOutlinedIcon sx={{ color: '#94A3B8', fontSize: '1.15rem' }} />
                        </InputAdornment>
                      ),
                      endAdornment: (
                        <InputAdornment position="end">
                          <Box
                            onClick={() => setShowPassword((p) => !p)}
                            sx={{ cursor: 'pointer', display: 'flex', color: '#94A3B8', '&:hover': { color: '#475569' } }}
                          >
                            {showPassword
                              ? <VisibilityOffOutlinedIcon sx={{ fontSize: '1.15rem' }} />
                              : <VisibilityOutlinedIcon sx={{ fontSize: '1.15rem' }} />}
                          </Box>
                        </InputAdornment>
                      ),
                    }}
                    autoComplete="current-password"
                    fullWidth
                    name="password"
                    onBlur={formik.handleBlur}
                    onChange={handleInputChange}
                    placeholder="Enter your password"
                    sx={FIELD_SX}
                    type={showPassword ? 'text' : 'password'}
                    value={formik.values.password}
                  />
                </Box>

                {/* Sign In */}
                <Button
                  autoFocus
                  disableElevation
                  disabled={!formValid || isLoading}
                  endIcon={!isLoading && formValid ? <ArrowForwardIcon sx={{ fontSize: '1rem !important' }} /> : undefined}
                  fullWidth
                  sx={{
                    mt: 0.5,
                    py: '13px',
                    borderRadius: '10px',
                    fontSize: '0.9375rem',
                    fontWeight: 700,
                    textTransform: 'none',
                    background: 'linear-gradient(135deg, #1E3A8A 0%, #2563EB 100%)',
                    boxShadow: '0 4px 14px rgba(37,99,235,0.35)',
                    transition: 'all 0.2s ease',
                    '&:hover': {
                      background: 'linear-gradient(135deg, #1e40af 0%, #1d4ed8 100%)',
                      boxShadow: '0 6px 20px rgba(37,99,235,0.45)',
                      transform: 'translateY(-1px)',
                    },
                    '&:active': { transform: 'translateY(0)' },
                    '&.Mui-disabled': {
                      background: '#F1F5F9',
                      color: '#94A3B8',
                      boxShadow: 'none',
                    },
                  }}
                  type="submit"
                  variant="contained"
                >
                  {isLoading ? (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <CircularProgress
                        size={16}
                        sx={{ color: appColors.white }}
                      />
                      <span>Signing in…</span>
                    </Box>
                  ) : 'Sign In'}
                </Button>

                {loginError && (
                  <Alert
                    severity="error"
                    sx={{
                      borderRadius: '10px',
                      alignItems: 'center',
                      border: '1px solid #FECACA',
                      backgroundColor: '#FEF2F2',
                      color: '#991B1B',
                      '& .MuiAlert-icon': { color: '#DC2626' },
                    }}
                  >
                    {loginError}
                  </Alert>
                )}

                {/* Divider */}
                <Divider sx={{ '&::before, &::after': { borderColor: '#F1F5F9' } }}>
                  <Typography sx={{ fontSize: '0.75rem', color: '#CBD5E1', px: 1 }}>or</Typography>
                </Divider>

                {/* Demo */}
                <Button
                  disableElevation
                  fullWidth
                  onClick={() => setNewUserOpen(true)}
                  sx={{
                    borderRadius: '10px',
                    textTransform: 'none',
                    fontSize: '0.875rem',
                    fontWeight: 600,
                    py: '11px',
                    color: '#2563EB',
                    border: '1.5px solid #DBEAFE',
                    backgroundColor: '#EFF6FF',
                    transition: 'all 0.2s ease',
                    '&:hover': {
                      backgroundColor: '#DBEAFE',
                      borderColor: '#93C5FD',
                      transform: 'translateY(-1px)',
                    },
                  }}
                  variant="outlined"
                >
                  New User? Try Demo
                </Button>

              </Stack>
            </Box>

            {/* Security note */}
            <Box sx={{ mt: 3, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6 }}>
              <ShieldOutlinedIcon sx={{ fontSize: '0.75rem', color: '#94A3B8' }} />
              <Typography sx={{ fontSize: '0.7rem', color: '#94A3B8', letterSpacing: '0.01em' }}>
                Protected by 256-bit SSL encryption
              </Typography>
            </Box>

          </Box>
        </Box>

        {/* Footer */}
        <Typography sx={{ textAlign: 'center', mt: 2.5, fontSize: '0.7rem', color: '#94A3B8' }}>
          © {new Date().getFullYear()} Nexshora POS · All rights reserved
        </Typography>

        <NewUserDialog
          onClose={() => setNewUserOpen(false)}
          onFillDemo={fillDemo}
          open={newUserOpen}
        />

      </Box>
    </Fade>
  );
};

export default React.memo(Login);
