import React, { useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import CalendarMonthOutlinedIcon from '@mui/icons-material/CalendarMonthOutlined';
import WarningAmberRoundedIcon from '@mui/icons-material/WarningAmberRounded';
import { useTranslation } from 'react-i18next';

interface IMobile {
  openModel?: boolean;
  handleCloseDialog: (close: boolean) => void;
  handlePay: (settleDate: string) => void;
}

const DateAlertPopup: React.FC<IMobile> = ({
  openModel = false,
  handleCloseDialog,
  handlePay,
}) => {
  const { t } = useTranslation(['common', 'sales', 'jewellerySale']);
  const [open] = useState(openModel);
  const today = new Date().toISOString().split('T')[0];
  const [settleDate, setSettleDate] = useState<string>(today);

  const handleClose = () => handleCloseDialog(false);
  const handlePayClick = () => { handlePay(settleDate); handleClose(); };

  return (
    <Dialog
      onClose={handleClose}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
          width: 440,
          maxWidth: 'calc(100vw - 32px)',
        },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: 'linear-gradient(135deg, #78350F 0%, #B45309 60%, #D97706 100%)',
            px: 3,
            py: 2,
          }}
        >
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <CalendarMonthOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                {t('jewellerySale:alert')}
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Set settlement date
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 2.5, pb: 1 }}>
        <Stack alignItems="flex-start" direction="row" spacing={1.5} sx={{ mb: 2 }}>
          <WarningAmberRoundedIcon sx={{ color: '#D97706', flexShrink: 0, fontSize: 20, mt: 0.1 }} />
          <Typography sx={{ color: '#475569', fontSize: '0.92rem', lineHeight: 1.6 }}>
            {t('jewellerySale:alertDueMessage')}
          </Typography>
        </Stack>
        <TextField
          InputLabelProps={{ shrink: true }}
          fullWidth
          inputProps={{ min: today }}
          label="Settlement Date"
          onChange={(e) => setSettleDate(e.target.value)}
          size="small"
          sx={{
            '& .MuiOutlinedInput-root': {
              borderRadius: '8px',
              '&.Mui-focused fieldset': { borderColor: '#D97706' },
            },
            '& label.Mui-focused': { color: '#D97706' },
          }}
          type="date"
          value={settleDate}
        />
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          onClick={handleClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          {t('sales:cancel')}
        </Button>
        <Button
          disabled={!settleDate}
          onClick={handlePayClick}
          sx={{
            background: 'linear-gradient(135deg, #78350F 0%, #D97706 100%)',
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(217,119,6,0.3)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { opacity: 0.9 },
            '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
          }}
          variant="contained"
        >
          {t('jewellerySale:pay')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default DateAlertPopup;
