import React, { useEffect, useMemo } from 'react';
import Box from '@mui/material/Box';
import { Badge, Grid, IconButton, Typography } from '@mui/material';
import { appColors, HEADER_GRADIENT } from '../../theme/appColors';
import ShoppingBasketOutlinedIcon from '@mui/icons-material/ShoppingBasketOutlined';
import ClearAllIcon from '@mui/icons-material/ClearAll';
import Summary from './components/Summary';
import SalesActionLeft, { SalesActionLeftHandle } from './components/SalesActionLeft';
import ItemCard from './components/ItemCard';
import SalesRight from './components/SalesRight';
import useSales from './useSales';
import JewelleryCustomer from './components/JewelleryCustomer';
import { useTranslation } from 'react-i18next';
import AnimatedPage from '../../layouts/AnimatedPage';
import { useGetUserQuery } from '../posApi';
import { IUserInfo } from '../../core/Interface/user.interface';
import { useAppDispatch } from '../../store/hooks';
import { removeBasket } from './store/BasketSlice';

const colHeader = (label: string, align: 'left' | 'right' = 'right') => (
  <Typography
    align={align}
    sx={{
      textTransform: 'uppercase',
      fontWeight: 700,
      fontSize: 9,
      color: 'rgba(255,255,255,0.85)',
      letterSpacing: '0.5px',
    }}
  >
    {label}
  </Typography>
);

const Jewellery = () => {
  const { calculateSummary, selectItem } = useSales();
  const { t } = useTranslation(['sales']);
  const { data: companyData } = useGetUserQuery();
  const dispatch = useAppDispatch();

  // Ref to SalesActionLeft — gives us pay() and openDiscount()
  const salesActionRef = React.useRef<SalesActionLeftHandle>(null);

  useEffect(() => {
    // Prevent body scroll
    const prevBody = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    // Prevent the <main> wrapper from scrolling (it has overflowY: auto from Main.tsx)
    const mainEl = document.querySelector('main') as HTMLElement | null;
    const prevMain = mainEl ? mainEl.style.overflowY : '';
    if (mainEl) mainEl.style.overflowY = 'hidden';

    return () => {
      document.body.style.overflow = prevBody;
      if (mainEl) mainEl.style.overflowY = prevMain;
    };
  }, []);

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  return (
    <AnimatedPage>
      {/*
        Height = 100vh − toolbar (56px xs / 64px sm+) − top/bottom padding
        xs:  100vh − 56 − 2×12 = calc(100vh − 80px)
        sm:  100vh − 64 − 2×16 = calc(100vh − 96px)
        lg:  100vh − 64 − 2×24 = calc(100vh − 112px)
      */}
      <Box
        sx={{
          height: {
            xs: 'calc(100vh - 80px)',
            sm: 'calc(100vh - 96px)',
            lg: 'calc(100vh - 112px)',
          },
          overflow: 'hidden',
        }}
      >
        <Grid container sx={{ height: '100%' }}>

          {/* ═══════════════════════ LEFT PANEL ═══════════════════════ */}
          <Grid
            item
            lg={4}
            md={4}
            sm={12}
            xs={12}
            sx={{
              display: 'flex',
              flexDirection: 'column',
              height: '100%',
              overflow: 'hidden',
            }}
          >
            <Box
              sx={{
                display: 'flex',
                flexDirection: 'column',
                height: '100%',
                overflow: 'hidden',
                backgroundColor: appColors.white,
                boxShadow: '2px 0 12px rgba(15,29,77,0.08)',
              }}
            >
              {/* ── Gradient header ── */}
              <Box
                sx={{
                  background: HEADER_GRADIENT,
                  px: 2,
                  py: 1,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  flexShrink: 0,
                }}
              >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                  <Badge
                    badgeContent={selectItem.length}
                    color="error"
                    max={99}
                    sx={{
                      '& .MuiBadge-badge': {
                        fontSize: '0.6rem',
                        fontWeight: 700,
                        minWidth: 17,
                        height: 17,
                      },
                    }}
                  >
                    <ShoppingBasketOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                  </Badge>
                  <Typography
                    sx={{
                      color: '#fff',
                      fontWeight: 800,
                      fontSize: '0.9rem',
                      letterSpacing: '0.3px',
                    }}
                  >
                    Jewellery Order
                  </Typography>
                </Box>

                {selectItem.length > 0 && (
                  <IconButton
                    onClick={() => dispatch(removeBasket())}
                    size="small"
                    sx={{
                      color: 'rgba(255,255,255,0.7)',
                      '&:hover': { color: '#fff', backgroundColor: 'rgba(255,255,255,0.12)' },
                    }}
                  >
                    <ClearAllIcon sx={{ fontSize: 18 }} />
                  </IconButton>
                )}
              </Box>

              {/* ── Customer + product search section ── */}
              <JewelleryCustomer />

              {/* ── Column headers ── */}
              <Box
                sx={{
                  background: 'rgba(15,29,77,0.80)',
                  px: '10px',
                  py: '5px',
                  flexShrink: 0,
                }}
              >
                <Grid container flexWrap="nowrap" spacing={0.5}>
                  <Grid item xs={4}>{colHeader('Item', 'left')}</Grid>
                  <Grid item xs={2}>{colHeader('Qty')}</Grid>
                  <Grid item xs={2}>{colHeader('Wt(g)')}</Grid>
                  <Grid item xs={3}>{colHeader('Amount')}</Grid>
                  <Grid item xs={1}>{colHeader('')}</Grid>
                </Grid>
              </Box>

              {/* ── Basket items — scrollable ── */}
              <Box sx={{ flex: 1, overflow: 'hidden', minHeight: 0 }}>
                <ItemCard />
              </Box>

              {/* ── Summary ── */}
              <Box sx={{ flexShrink: 0 }}>
                <Summary
                  currencyCode={currencyCode}
                  discount={calculateSummary.discount}
                  subtotal={calculateSummary.subTotal}
                  total={calculateSummary.total}
                />
                {/* Invisible: mounts Invoice/print/popups and exposes pay() */}
                <SalesActionLeft ref={salesActionRef} />
              </Box>
            </Box>
          </Grid>

          {/* ═══════════════════════ RIGHT PANEL ══════════════════════ */}
          <Grid
            item
            lg={8}
            md={8}
            sm={12}
            xs={12}
            sx={{ height: '100%', overflow: 'hidden' }}
          >
            <SalesRight
              hasItems={selectItem.length > 0}
              isPayLoading={false}
              onDiscount={() => salesActionRef.current?.openDiscount()}
              onPay={() => salesActionRef.current?.pay()}
              paymentStatus={false}
            />
          </Grid>
        </Grid>
      </Box>
    </AnimatedPage>
  );
};

export default Jewellery;
