import { useSelector } from 'react-redux';
import {
  finalSummaryStare,
  selectBasket,
  selectBasketItems,
  selectDiscount,
  addBalance,
} from './store/BasketSelector';
import { useMemo } from 'react';
import {
  IJewellerySalesItem,
  IJewellerySalesReqPayload,
} from '../../core/Interface/saleJewellery.interface';
import { IJewelleryBasketItem } from '../../core/Interface/saleJewellery.interface';

const toFixedDown = (num: number): number => {
  return Math.round(num * 100) / 100;
};

const useSales = () => {
  const selectItem = useSelector(selectBasketItems);
  const selectDis = useSelector(selectDiscount);
  const paymentStatus = useSelector(finalSummaryStare);
  const selectBalance = useSelector(addBalance);
  const selectBasketStore = useSelector(selectBasket);

  const calculateSummary: {
    subTotal: number;
    discount: number;
    total: number;
  } = useMemo(() => {
    const subTotal = selectItem.reduce(getSum, 0);
    const discount = !selectDis.discountAsPercentage
      ? selectDis.discount
      : (subTotal * selectDis.discount) / 100;
    const total = subTotal === 0 ? 0 : subTotal - discount;

    return {
      subTotal: toFixedDown(subTotal),
      discount: toFixedDown(discount),
      total: toFixedDown(total),
    };
  }, [selectDis.discount, selectDis.discountAsPercentage, selectItem]);

  const salesDetails: IJewellerySalesReqPayload = {
    mobile: selectBasketStore.mobile ?? '',
    customerName: selectBasketStore.customerName ?? '',
    dateTime: new Date().toISOString(),
    subTotal: calculateSummary.subTotal,
    isDiscountPercentage: !!selectDis.discountAsPercentage,
    discountValue: toFixedDown(selectDis.discount),
    discount: calculateSummary.discount,
    totalDiscount: calculateSummary.discount,
    total: calculateSummary.total,
    received: selectBasketStore.receivedAmount ?? 0,
    items: selectItem.map((item) => {
      const goldValue =
        ((item.goldWeightQty ?? 0) + (item.goldWasteQty ?? 0)) *
        ((item.goldPrice8g ?? 0) / 8);
      const itemAmount = goldValue + (item.makingCharge ?? 0);

      const lineDiscount = item.defaultDiscountAmount
        ? item.isDiscountPercentage
          ? ((itemAmount * (item.defaultDiscountAmount ?? 0)) / 100) *
            item.count
          : (item.defaultDiscountAmount ?? 0) * item.count
        : 0;

      const guidProductId = String(item.id).split('__v')[0];

      return {
        productId: guidProductId,
        qty: item.count,
        goldWeightQty: item.goldWeightQty ?? 0,
        goldWasteQty: item.goldWasteQty ?? 0,
        goldCarrot: item.goldCarrot ?? '22K',
        makingCharge: item.makingCharge ?? 0,
        unitPrice: toFixedDown(item.goldPrice8g ?? 0),
        amount: toFixedDown(itemAmount - lineDiscount),
      } as IJewellerySalesItem;
    }),
    balance: selectBalance,
    referenceId: selectBasketStore.referenceId,
    whatsAppShareLink: '',
    paymentMethod: selectBasketStore.paymentMethod ?? '',
    isPaid: true,
    creditSettleDate:''
  };

  return { calculateSummary, selectItem, salesDetails, paymentStatus };
};

function getSum(total: number, item: IJewelleryBasketItem) {
  return (
    total +
    (item.goldWeightQty ?? 0) * ((item.goldPrice8g ?? 0) / 8) +
    (item.makingCharge ?? 0) +
    (item.goldWasteQty ?? 0) * ((item.goldPrice8g ?? 0) / 8)
  );
}

export default useSales;
