import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  FormControl,
  MenuItem,
  OutlinedInput,
  Select,
  Stack,
  Typography,
  useMediaQuery,
} from '@mui/material';
import BusinessOutlinedIcon from '@mui/icons-material/BusinessOutlined';
import { useTranslation } from 'react-i18next';
import { useEffect, useMemo, useState } from 'react';
import { IAuth } from '../../core/Interface/api.interface';
import { theme } from '../../theme';
import { useBranchSwitchMutation, useGetAllBranchQuery } from '../../page/posApi';
import { HEADER_GRADIENT } from '../../theme/appColors';
import FieldHeader from '../FieldHeader';
import { useNotifier } from '../../core/Notifier';
import { useAppDispatch } from '../../store/hooks';
import { setEnableAuth } from '../../page/Auth/AuthSlice';
import { IBranchDetails } from '../../core/Interface/branch.interface';

interface IBranchChange {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  onTokenChange: () => void;
  selectedBranch: string;
}

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: { maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP, width: 250 },
  },
};

const BranchChange = ({
  title,
  openModel = false,
  handleCloseDialog,
  onTokenChange,
  selectedBranch,
}: IBranchChange) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { t } = useTranslation(['branchManage', 'common']);

  const [branchSwitchData, { isLoading: branchSwitchDataLoading }] = useBranchSwitchMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const dispatch = useAppDispatch();

  const { data: branchChangeData } = useGetAllBranchQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });

  const [selectedBranchId, setSelectedBranchId] = useState<string | null>(null);

  const handleBranchSwitchData = async (id: string) => {
    try {
      const response = await branchSwitchData(id).unwrap();
      if (response.status) {
        showMessage(response.message);
        const tokenData = response.data as IAuth;
        localStorage.setItem('token', tokenData.token);
        onTokenChange();
        dispatch(setEnableAuth());
        handleClose();
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const handleSwitchBranch = () => {
    if (selectedBranchId) handleBranchSwitchData(selectedBranchId);
  };

  const branchList = useMemo(() => branchChangeData?.data as IBranchDetails, [branchChangeData?.data]);

  const handleClose = () => handleCloseDialog(false);

  useEffect(() => {
    setSelectedBranchId(selectedBranch);
    const initialBranch = branchList?.records.find((branch) => branch.name === selectedBranch);
    if (initialBranch) setSelectedBranchId(initialBranch.id);
  }, [selectedBranch, branchList?.records]);

  return (
    <div>
      <form>
        <Dialog
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="xs"
          open={open}
          PaperProps={{
            sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' },
          }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box
                  sx={{
                    alignItems: 'center',
                    background: 'rgba(255,255,255,0.15)',
                    borderRadius: '8px',
                    display: 'flex',
                    height: 36,
                    justifyContent: 'center',
                    width: 36,
                    flexShrink: 0,
                  }}
                >
                  <BusinessOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                    {title}
                  </Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                    Switch active branch
                  </Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>

          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <FieldHeader title="Branch List" />
            <FormControl sx={{ width: '100%' }}>
              <Select
                MenuProps={MenuProps}
                input={<OutlinedInput sx={{ height: 40, borderRadius: '8px' }} />}
                onChange={(event) => setSelectedBranchId(event.target.value as string)}
                value={selectedBranchId || ''}
              >
                {branchList?.records.map((branch) => (
                  <MenuItem key={branch.id} value={branch.id}>
                    {`${branch.name} - ${branch.code}`}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </DialogContent>

          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                borderColor: '#CBD5E1',
                borderRadius: '8px',
                color: '#475569',
                fontWeight: 600,
                height: 40,
                minWidth: 100,
                px: 3,
                textTransform: 'none',
                '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!selectedBranchId || branchSwitchDataLoading}
              onClick={handleSwitchBranch}
              sx={{
                background: HEADER_GRADIENT,
                borderRadius: '8px',
                boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
                color: '#fff',
                fontWeight: 700,
                height: 40,
                minWidth: 100,
                px: 3,
                textTransform: 'none',
                '&:hover': { opacity: 0.9 },
                '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
              }}
              type="submit"
              variant="contained"
            >
              {branchSwitchDataLoading
                ? <CircularProgress size={16} sx={{ color: '#fff' }} />
                : t('branchManage:switch')}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(BranchChange);
