import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  FormControl,
  Grid,
  IconButton,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useNewCustomerMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { useTranslation } from 'react-i18next';
import { uploadImage } from '../../../core/utils';
import { useMemo } from 'react';
import { ICustomerDetailsData } from '../../../core/Interface/customer.interface';
import PersonAddOutlinedIcon from '@mui/icons-material/PersonAddOutlined';
import CloseIcon from '@mui/icons-material/Close';
import { HEADER_GRADIENT } from '../../../theme/appColors';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

interface INewCustomer {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: Partial<ICustomerDetailsData>;
  onSuccess?: (mobile: string) => void;
  isImageEnabled: boolean;
}

const NewCustomer = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
  onSuccess,
  isImageEnabled,
}: INewCustomer) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newCustomer, { isLoading }] = useNewCustomerMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'category', 'customer']);
  const buttonText = data ? t('common:update') : t('common:create');

  const handleClose = () => { handleCloseDialog(false); };

  // eslint-disable-next-line max-len
  const [selectedImage, setSelectedImage] = React.useState<File | undefined>(undefined);
  const [isImageUploading, setIsImageUploading] = React.useState(false);

  const validateMobileNumber = (value: string) => {
    if (value.startsWith('0')) {
      return /^[0-9]{10}$/.test(value);
    }
    return /^[1-9]{9}$/.test(value);
  };

  const validateName = (value: string) => /\S/.test(value);

  const formik = useFormik({
    initialValues: {
      id: data?.id,
      name: data?.name,
      address: data?.address,
      email: data?.email,
      mobile: data?.mobile,
      imageUrl: data?.imageUrl,
      creditLimit: data?.creditLimit,
    },
    onSubmit: async (values) => {
      try {
        let imageUrl: string | undefined = data?.imageUrl;
        if (selectedImage) {
          setIsImageUploading(true);
          imageUrl = (await uploadImage(selectedImage)) || '';
          setIsImageUploading(false);
        }
        if (!validateMobileNumber(values.mobile || '')) {
          showErrorMessage('Mobile number should be valid.');
          return;
        }
        if (!validateName(values.name || '')) {
          showErrorMessage('Please enter only letters. ');
          return;
        }
        values.imageUrl = imageUrl;
        const temData = {
          id: values?.id,
          name: values.name,
          mobile: values?.mobile || '',
          email: values?.email,
          address: values.address,
          creditLimit: values.creditLimit,
          imageUrl,
        };
        if (!data) delete values.id;
        const res = await newCustomer(temData).unwrap();
        if (!res.status) {
          showErrorMessage(res.message);
        } else {
          showMessage(res.message);
          // eslint-disable-next-line max-len
          if (formik.values.mobile && onSuccess) onSuccess(formik.values.mobile);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(
    () => !(
      formik.values.name === '' ||
      formik.values.name === undefined ||
      formik.values.mobile === '' ||
      formik.values.mobile === undefined
    ),
    [formik],
  );

  const handleImageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    setSelectedImage(file ?? undefined);
  };

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          PaperProps={{
            sx: {
              borderRadius: isMobile ? 0 : '12px',
              overflow: 'hidden',
            },
          }}
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="sm"
          open={open}
        >
          {/* ── Gradient header ─────────────────────────────────── */}
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <PersonAddOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Create or edit customer</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>

          {/* ── Form content ────────────────────────────────────── */}
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <Grid container>
              <FieldItem label={t('customer:title.name')}>
                <TextField
                  autoComplete="off"
                  error={
                    formik.touched.name && !validateName(formik.values.name || '')
                  }
                  fullWidth
                  helperText={
                    formik.touched.name &&
                    !validateName(formik.values.name || '') && (
                      <span style={{ textTransform: 'none' }}>
                        Name cannot be empty or contain only spaces.
                      </span>
                    )
                  }
                  placeholder={t('customer:title.name')}
                  size="small"
                  {...formik.getFieldProps('name')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label={t('customer:title.mobile')}>
                <TextField
                  autoComplete="off"
                  error={
                    formik.touched.mobile &&
                    !validateMobileNumber(formik.values.mobile || '')
                  }
                  fullWidth
                  helperText={
                    formik.touched.mobile &&
                    !validateMobileNumber(formik.values.mobile || '') && (
                      <span style={{ textTransform: 'none' }}>
                        Please enter valid mobile number.
                      </span>
                    )
                  }
                  inputProps={{ maxLength: 10, type: 'tel' }}
                  placeholder={t('customer:title.mobile')}
                  size="small"
                  {...formik.getFieldProps('mobile')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label={t('customer:title.address')}>
                <TextField
                  autoComplete="off"
                  fullWidth
                  placeholder={t('customer:title.address')}
                  size="small"
                  {...formik.getFieldProps('address')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label={t('customer:title.email')}>
                <TextField
                  autoComplete="off"
                  fullWidth
                  placeholder={t('customer:title.email')}
                  size="small"
                  {...formik.getFieldProps('email')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label={t('customer:title.creditLimit')}>
                <TextField
                  autoComplete="off"
                  fullWidth
                  placeholder={t('customer:title.creditLimit')}
                  size="small"
                  {...formik.getFieldProps('creditLimit')}
                  sx={fieldSx}
                />
              </FieldItem>

              {isImageEnabled && (
                <FieldItem label={t('customer:title.upload image')}>
                  <FormControl sx={{ width: '100%' }}>
                    <Box
                      sx={{
                      alignItems: 'center',
                      background: alpha(TEAL, 0.03),
                      border: `2px dashed ${alpha(TEAL, 0.3)}`,
                      borderRadius: '10px',
                      display: 'flex',
                      flexDirection: 'column',
                      height: 160,
                      justifyContent: 'center',
                      padding: '12px',
                    }}
                    >
                      <Grid
                        container
                        spacing={1}
                      >
                        <Grid
                          item
                          xs={8}
                        >
                          {selectedImage && (
                            <img
                              alt="Selected"
                              height="136px"
                              src={URL.createObjectURL(selectedImage)}
                              style={{ borderRadius: '6px', objectFit: 'cover' }}
                              width="100%"
                            />
                          )}
                          {!selectedImage && data?.imageUrl && (
                            <img
                              alt="Selected"
                              height="136px"
                              src={data.imageUrl}
                              style={{ borderRadius: '6px', objectFit: 'cover' }}
                              width="100%"
                            />
                          )}
                        </Grid>
                        <Grid
                          item
                          xs={4}
                        >
                          <TextField
                            InputProps={{
                              inputProps: { accept: '.jpg,.jpeg,.png' },
                            }}
                            onChange={handleImageChange}
                            size="small"
                            sx={fieldSx}
                            type="file"
                          />
                          {isImageUploading && (
                            <Box sx={{ mt: 1 }}>
                              <CircularProgress
                                size={16}
                                sx={{ color: TEAL }}
                              />
                            </Box>
                          )}
                        </Grid>
                      </Grid>
                    </Box>
                  </FormControl>
                </FieldItem>
              )}
            </Grid>
          </DialogContent>

          {/* ── Actions ─────────────────────────────────────────── */}
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                borderColor: '#CBD5E1',
                borderRadius: '8px',
                color: '#475569',
                fontWeight: 600,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading}
              onClick={() => { formik.handleSubmit(); }}
              sx={{
                background: HEADER_GRADIENT,
                borderRadius: '8px',
                boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
                color: '#fff',
                fontWeight: 700,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { opacity: 0.9 },
                '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
              }}
              type="submit"
              variant="contained"
            >
              {isLoading ? (
                <CircularProgress
                  size={18}
                  sx={{ color: '#fff' }}
                />
              ) : buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewCustomer);

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(TEAL, 0.03),
    borderRadius: '8px',
    '& fieldset': { borderColor: alpha(TEAL, 0.2) },
    '&.Mui-focused fieldset': { borderColor: TEAL },
    '&:hover fieldset': { borderColor: alpha(TEAL, 0.4) },
  },
};

// eslint-disable-next-line react/no-multi-comp
const FieldItem = ({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) => (
  <Grid
    item
    lg={12}
    sm={12}
    sx={{ pb: 2 }}
    xs={12}
  >
    <Typography
      sx={{
      color: alpha(NAVY, 0.5),
      fontSize: 11,
      fontWeight: 700,
      letterSpacing: '0.5px',
      mb: 0.75,
      textTransform: 'uppercase',
    }}
    >
      {label}
    </Typography>
    {children}
  </Grid>
);
