import React, { useMemo } from 'react';
import { TableRow, TableCell, Skeleton } from '@mui/material';

interface ISkeletonTable {
  cellCount?: number;
  rowCount?: number;
  skeletonHeight?: number;
}

const SkeletonTable: React.FC<ISkeletonTable> = ({
  rowCount = 5,
  cellCount = 5,
  skeletonHeight = 20,
}) => {
  const rowArray = useMemo(() => Array.from({ length: rowCount }), [rowCount]);
  const columnArray = useMemo(
    () => Array.from({ length: cellCount }),
    [cellCount]
  );

  return (
    <>
      {rowArray.map((_, rowIndex) => (
        <TableRow key={rowIndex}>
          {columnArray.map((index, colIndex) => (
            <TableCell
              key={colIndex}
              sx={{ p: 1 }}
            >
              <Skeleton
                height={skeletonHeight}
                variant="rounded"
              />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
};

export default React.memo(SkeletonTable);
